const BASE_PRICES: Record<string, number> = {
  sword: 100,
  amulet: 60,
};

const FIRST_CONTRACT_SURCHARGE = 1.1;
const CONTRACT_FEE = 5;

export const run = (scenario: Scenario): ScenarioResult => {
  const basePrice = BASE_PRICES[scenario.steps[0].items[0].type];
  const premium = basePrice * FIRST_CONTRACT_SURCHARGE + CONTRACT_FEE;
  return { results: [{ premium }] };
};

